#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <numeric>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(3));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> edges[i][j];
        }
    }

    const long long INF = 1000000000000000000LL;
    vector<int> order(m);
    for (int i = 0; i < m; i++) order[i] = i;
    sort(order.begin(), order.end(), [&](int x, int y) { return edges[x][2] < edges[y][2]; });
    auto kruskal = [&](int skip, int force) {
        vector<int> parent(n + 1);
        for (int v = 0; v <= n; v++) parent[v] = v;
        auto find = [&](int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        };
        long long total = 0, taken = 0;
        if (force >= 0) {
            parent[find((int)edges[force][0])] = find((int)edges[force][1]);
            total += edges[force][2];
            taken++;
        }
        for (int i : order) {
            if (i == skip || i == force) continue;
            int a = find((int)edges[i][0]), b = find((int)edges[i][1]);
            if (a != b) {
                parent[a] = b;
                total += edges[i][2];
                taken++;
            }
        }
        return taken == n - 1 ? total : INF;
    };
    long long best = kruskal(-1, -1);
    vector<int> critical, pseudo;
    for (int i = 0; i < m; i++) {
        if (kruskal(i, -1) > best) critical.push_back(i + 1);
        else if (kruskal(-1, i) == best) pseudo.push_back(i + 1);
    }
    cout << critical.size();
    for (int x : critical) cout << " " << x;
    cout << "\n" << pseudo.size();
    for (int x : pseudo) cout << " " << x;
    cout << "\n";

    return 0;
}

